  "CivicConnect is an internal grievance workflow. It is not an emergency service — for immediate danger to life, contact local emergency services.": "CivicConnect एक आंतरिक शिकायत प्रणाली है। यह आपातकालीन सेवा नहीं है — जान के तत्काल खतरे में स्थानीय आपातकालीन सेवाओं से संपर्क करें।",
  "CivicConnect is not an emergency service. If there is an immediate threat to life or safety, contact local emergency services now. Your report will also be flagged for prompt human review.": "CivicConnect आपातकालीन सेवा नहीं है। जान या सुरक्षा को तत्काल खतरा हो तो अभी स्थानीय आपातकालीन सेवाओं से संपर्क करें। आपकी रिपोर्ट को तुरंत मानवीय जाँच के लिए चिह्नित भी किया जाएगा।",
  "CivicConnect public grievance system": "CivicConnect सार्वजनिक शिकायत प्रणाली",
  "Clarification requested": "स्पष्टीकरण माँगा गया",
  "Clarification requested from the citizen.": "नागरिक से स्पष्टीकरण माँगा गया।",
  "Clear": "साफ़ करें",
  "Clear all": "सभी साफ़ करें",
  "Click the map to add boundary points ({n}). At least 3 are needed.": "सीमा बिंदु जोड़ने के लिए मानचित्र पर क्लिक करें ({n})। कम से कम 3 चाहिए।",
  "Close": "बंद करें",
  "Close escalation": "एस्केलेशन बंद करें",
  "Closed": "बंद",
  "Comments (optional)": "टिप्पणियाँ (वैकल्पिक)",
  "Complaint": "शिकायत",
  "Complaint category": "शिकायत श्रेणी",
  "Complaint lifecycle": "शिकायत जीवनचक्र",
  "Complaint reassigned.": "शिकायत दोबारा सौंपी गई।",
  "Complaint submitted": "शिकायत जमा हो गई",
  "Complaint trend": "शिकायतों का रुझान",
  "Complaints": "शिकायतें",
  "Complaints are matched to the deepest jurisdiction whose boundary contains their location. Levels without a boundary are reached through their sub-jurisdictions.": "शिकायतें उस सबसे गहरे क्षेत्राधिकार से मिलाई जाती हैं जिसकी सीमा में उनका स्थान है। बिना सीमा वाले स्तर उनके उप-क्षेत्राधिकारों से पहुँचे जाते हैं।",
  "Complaints assigned to you and complaints in your operational areas.": "आपको सौंपी गई शिकायतें और आपके कार्य क्षेत्रों की शिकायतें।",
  "Complaints awaiting routing review": "रूटिंग समीक्षा की प्रतीक्षा वाली शिकायतें",
  "Complaints by jurisdiction": "क्षेत्राधिकार के अनुसार शिकायतें",
  "Complaints located in these areas (and their sub-areas) are assigned to this officer automatically. Leave all unticked to cover the whole unit.": "इन क्षेत्रों (और उप-क्षेत्रों) की शिकायतें इस अधिकारी को स्वचालित रूप से सौंपी जाती हैं। पूरी इकाई कवर करने के लिए सभी को अचयनित छोड़ें।",
  "Complaints not resolved within their deadline are escalated automatically: first to the department administrator, then to the main administration. Officers and department administrators can also escalate manually.": "समय सीमा में हल न होने वाली शिकायतें स्वचालित रूप से एस्केलेट होती हैं: पहले विभाग प्रशासक को, फिर मुख्य प्रशासन को। अधिकारी और विभाग प्रशासक भी स्वयं एस्केलेट कर सकते हैं।",
  "Complaints received": "शिकायतें प्राप्त",
  "Complaints routed to your unit that have no officer yet, usually because no active officer covers the location. Open a complaint to assign it.": "आपकी इकाई को भेजी गई शिकायतें जिनका अभी कोई अधिकारी नहीं है, आमतौर पर क्योंकि कोई सक्रिय अधिकारी उस स्थान को कवर नहीं करता। सौंपने के लिए शिकायत खोलें।",
  "Complaints submitted and resolved per week, last 12 weeks": "प्रति सप्ताह दर्ज और हल की गई शिकायतें, पिछले 12 सप्ताह",
  "Complaints that cannot be routed automatically appear here. Nothing is ever discarded.": "जो शिकायतें स्वचालित रूप से नहीं भेजी जा सकतीं, वे यहाँ दिखती हैं। कुछ भी कभी हटाया नहीं जाता।",
  "Complaints that describe a possible immediate danger are flagged for prompt human review.": "संभावित तत्काल खतरे वाली शिकायतें शीघ्र मानवीय समीक्षा के लिए चिह्नित होती हैं।",
  "Confidence": "विश्वास स्तर",
  "Configuration": "कॉन्फ़िगरेशन",
  "Configure jurisdictions, departments, unit mapping, responsibilities, staff, escalation rules and public issues. See the governance overview.": "क्षेत्राधिकार, विभाग, इकाई मैपिंग, ज़िम्मेदारियाँ, कर्मचारी, एस्केलेशन नियम और सार्वजनिक समस्याएँ कॉन्फ़िगर करें। शासन अवलोकन देखें।",
  "Configure the inputs under": "इनपुट यहाँ कॉन्फ़िगर करें:",
  "Configured": "कॉन्फ़िगर किया गया",
  "Configured jurisdiction and responsibility rules decide where it goes. Unclear cases get human review.": "तय क्षेत्र और ज़िम्मेदारी नियम तय करते हैं कि शिकायत कहाँ जाएगी। अस्पष्ट मामलों की मानवीय जाँच होती है।",
