  "System health and fixed workflow rules. Technical details are kept here, away from the operational overview.": "प्रणाली स्वास्थ्य और तय कार्यप्रवाह नियम। तकनीकी विवरण यहाँ, संचालन अवलोकन से अलग रखे गए हैं।",
