  "The citizen chose not to allow public display of this complaint.": "नागरिक ने इस शिकायत के सार्वजनिक प्रदर्शन की अनुमति नहीं दी।",
  "The citizen reported a possible immediate safety concern. Review promptly.": "नागरिक ने संभावित तत्काल सुरक्षा खतरे की सूचना दी। तुरंत समीक्षा करें।",
  "The configuration is not valid JSON.": "कॉन्फ़िगरेशन मान्य JSON नहीं है।",
  "The demonstration uses a separate database with sample data. No emails or messages are sent, and nothing here affects real complaints. Any visitor can reset it.": "प्रदर्शन नमूना डेटा वाले अलग डेटाबेस का उपयोग करता है। कोई ईमेल या संदेश नहीं भेजे जाते, और यहाँ कुछ भी वास्तविक शिकायतों को प्रभावित नहीं करता। कोई भी आगंतुक इसे रीसेट कर सकता है।",
  "The department reports this issue as resolved. It has not yet been verified.": "विभाग ने इस समस्या को हल बताया है। इसका अभी सत्यापन नहीं हुआ।",
  "The department will handle complaints in this jurisdiction and all of its sub-jurisdictions, unless a closer unit exists.": "यह विभाग इस क्षेत्राधिकार और इसके सभी उप-क्षेत्राधिकारों की शिकायतें संभालेगा, जब तक कोई निकट इकाई न हो।",
  "The location decides the jurisdiction, and configured rules decide the responsible department and officer.": "स्थान क्षेत्राधिकार तय करता है, और कॉन्फ़िगर नियम ज़िम्मेदार विभाग और अधिकारी तय करते हैं।",
  "The neighbourhood": "पूरा मोहल्ला",
  "The whole street": "पूरी गली",
  "These are AI suggestions, not decisions. Please verify everything before using it.": "ये AI सुझाव हैं, फ़ैसले नहीं। इस्तेमाल से पहले सब कुछ जाँचें।",
  "These configuration items will be removed with it:": "ये कॉन्फ़िगरेशन आइटम भी साथ हट जाएँगे:",
  "These help the department prioritize. Leave anything you are unsure about blank — we never fill in values for you.": "इनसे विभाग को प्राथमिकता तय करने में मदद मिलती है। जिस बारे में पक्का न हों, उसे खाली छोड़ें — हम आपकी जगह कुछ नहीं भरते।",
  "This browser does not support notifications.": "यह ब्राउज़र सूचनाओं का समर्थन नहीं करता।",
  "This complaint was assigned to you. Accept it to confirm you are working on it.": "यह शिकायत आपको सौंपी गई है। आप इस पर काम कर रहे हैं, इसकी पुष्टि के लिए इसे स्वीकार करें।",
  "This file format is not supported. Please upload a supported image, audio or video file.": "यह फ़ाइल प्रारूप समर्थित नहीं है। कृपया समर्थित फ़ोटो, ऑडियो या वीडियो फ़ाइल अपलोड करें।",
  "This is an internal CivicConnect reference, not a government complaint number.": "यह CivicConnect की आंतरिक संदर्भ संख्या है, सरकारी शिकायत संख्या नहीं।",
  "This is an internal CivicConnect workflow. It has not been submitted to any government portal.": "यह CivicConnect का आंतरिक कार्यप्रवाह है। इसे किसी सरकारी पोर्टल पर नहीं भेजा गया है।",
  "This is not an emergency service. For emergencies call 112.": "यह आपातकालीन सेवा नहीं है। आपात स्थिति में 112 पर कॉल करें।",
  "This permanently removes the record. It cannot be undone.": "यह रिकॉर्ड को स्थायी रूप से हटा देता है। इसे वापस नहीं किया जा सकता।",
  "This record is still in use and cannot be deleted.": "यह रिकॉर्ड अभी उपयोग में है और हटाया नहीं जा सकता।",
  "This sends the complaint to the main administration (level 2) with your reason.": "यह आपके कारण के साथ शिकायत को मुख्य प्रशासन (स्तर 2) को भेजता है।",
  "This sends the complaint to your department administrator (level 1) with your reason.": "यह आपके कारण के साथ शिकायत को आपके विभाग प्रशासक (स्तर 1) को भेजता है।",
  "Tick only for sample or test data.": "केवल नमूना या परीक्षण डेटा के लिए चुनें।",
  "Time allowed from submission to resolution, by priority. Set these to the authority's own service standards.": "प्राथमिकता के अनुसार दर्ज करने से समाधान तक अनुमत समय। इन्हें प्राधिकरण के अपने सेवा मानकों के अनुसार सेट करें।",
  "Title": "शीर्षक",
