  "Weights must add up to 1.0, and thresholds must satisfy CRITICAL > HIGH > MEDIUM. Every change creates a new audited version.": "भारों का योग 1.0 होना चाहिए, और सीमाएँ अति गंभीर > उच्च > मध्यम होनी चाहिए। हर बदलाव एक नया ऑडिट संस्करण बनाता है।",
