  "When did you first notice it?": "आपने इसे पहली बार कब देखा?",
  "When you report a civic issue, it will appear here with its reference ID and live status.": "जब आप कोई समस्या दर्ज करेंगे, वह यहाँ संदर्भ संख्या और ताज़ा स्थिति के साथ दिखेगी।",
