  "Who is affected and why it matters publicly.": "कौन प्रभावित है और यह सार्वजनिक रूप से क्यों महत्वपूर्ण है।",
  "Who is affected?": "किस पर असर है?",
  "Whole unit": "पूरी इकाई",
  "Without responsibilities, complaints cannot be routed and wait in administrative review.": "ज़िम्मेदारियों के बिना शिकायतें भेजी नहीं जा सकतीं और प्रशासनिक समीक्षा में रहती हैं।",
