  "Write a summary with no names, phone numbers or private details.": "नाम, फ़ोन नंबर या निजी विवरण के बिना सारांश लिखें।",
  "Write for the public. Do not include names, phone numbers, house numbers or other personal details.": "जनता के लिए लिखें। नाम, फ़ोन नंबर, मकान नंबर या अन्य व्यक्तिगत विवरण शामिल न करें।",
  "Write or speak in your language, and optionally add photos, a voice note or a short video.": "अपनी भाषा में लिखें या बोलें, और चाहें तो फ़ोटो, वॉइस नोट या छोटा वीडियो जोड़ें।",
  "Yes, it looks resolved": "हाँ, यह हल लगती है",
  "You always get updates here in the app. You can also get them by email, SMS or browser notification.": "आपको अपडेट हमेशा यहाँ ऐप में मिलते हैं। आप इन्हें ईमेल, SMS या ब्राउज़र सूचना से भी पा सकते हैं।",
  "You can still submit if your issue is separate — your report is always kept as its own record.": "अगर आपकी समस्या अलग है तो आप फिर भी जमा कर सकते हैं — आपकी रिपोर्ट हमेशा अलग रिकॉर्ड रहती है।",
  "You can upload a maximum of 5 images per complaint.": "हर शिकायत में अधिकतम 5 फ़ोटो अपलोड कर सकते हैं।",
  "You can write or speak in English, Hindi, Kannada or any language you are comfortable with.": "आप अंग्रेज़ी, हिंदी, कन्नड़ या अपनी सुविधा की किसी भी भाषा में लिख या बोल सकते हैं।",
