  "Your account is not linked to a department unit yet. Ask the main administration to configure it.": "आपका खाता अभी किसी विभाग इकाई से जुड़ा नहीं है। मुख्य प्रशासन से इसे कॉन्फ़िगर करने को कहें।",
  "Your department administrator verifies and approves publication.": "आपके विभाग प्रशासक सत्यापन और प्रकाशन की स्वीकृति देते हैं।",
