  "Ask the main administration to add officers. Until then, complaints wait in the unassigned queue.": "ಅಧಿಕಾರಿಗಳನ್ನು ಸೇರಿಸಲು ಮುಖ್ಯ ಆಡಳಿತವನ್ನು ಕೇಳಿ. ಅಲ್ಲಿಯವರೆಗೆ ದೂರುಗಳು ನಿಯೋಜಿಸದ ಸರತಿಯಲ್ಲಿ ಇರುತ್ತವೆ.",
  "Assessment": "ಮೌಲ್ಯಮಾಪನ",
  "Assign": "ನಿಯೋಜಿಸಿ",
  "Assign an officer to continue.": "ಮುಂದುವರಿಯಲು ಅಧಿಕಾರಿಯನ್ನು ನಿಯೋಜಿಸಿ.",
  "Assign officer": "ಅಧಿಕಾರಿಯನ್ನು ನಿಯೋಜಿಸಿ",
  "Assigned": "ನಿಯೋಜಿಸಲಾಗಿದೆ",
  "Assigned automatically by area": "ಪ್ರದೇಶದ ಆಧಾರದ ಮೇಲೆ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ನಿಯೋಜಿಸಲಾಗಿದೆ",
  "Assigned by {name}": "{name} ನಿಯೋಜಿಸಿದ್ದಾರೆ",
