  "Report potholes, water leaks, overflowing garbage, blocked drains, broken streetlights and damaged public facilities. Follow your complaint from submission to verified resolution.": "ರಸ್ತೆ ಗುಂಡಿ, ನೀರಿನ ಸೋರಿಕೆ, ತುಂಬಿದ ಕಸ, ಕಟ್ಟಿದ ಚರಂಡಿ, ಕೆಟ್ಟ ಬೀದಿದೀಪ ಮತ್ತು ಹಾಳಾದ ಸಾರ್ವಜನಿಕ ಸೌಲಭ್ಯಗಳ ಬಗ್ಗೆ ವರದಿ ಮಾಡಿ. ಸಲ್ಲಿಕೆಯಿಂದ ಪರಿಶೀಲಿತ ಪರಿಹಾರದವರೆಗೆ ನಿಮ್ಮ ದೂರನ್ನು ಅನುಸರಿಸಿ.",
