  "Thank you. Your confirmation was recorded.": "ಧನ್ಯವಾದಗಳು. ನಿಮ್ಮ ದೃಢೀಕರಣ ದಾಖಲಾಗಿದೆ.",
  "The GeoJSON could not be read.": "GeoJSON ಓದಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.",
  "The citizen chose not to allow public display of this complaint.": "ಈ ದೂರಿನ ಸಾರ್ವಜನಿಕ ಪ್ರದರ್ಶನಕ್ಕೆ ನಾಗರಿಕರು ಅನುಮತಿಸಿಲ್ಲ.",
  "The citizen reported a possible immediate safety concern. Review promptly.": "ನಾಗರಿಕರು ಸಂಭಾವ್ಯ ತಕ್ಷಣದ ಸುರಕ್ಷತಾ ಸಮಸ್ಯೆ ವರದಿ ಮಾಡಿದ್ದಾರೆ. ತಕ್ಷಣ ಪರಿಶೀಲಿಸಿ.",
  "The configuration is not valid JSON.": "ಸಂರಚನೆ ಮಾನ್ಯ JSON ಅಲ್ಲ.",
  "The demonstration uses a separate database with sample data. No emails or messages are sent, and nothing here affects real complaints. Any visitor can reset it.": "ಪ್ರದರ್ಶನವು ಮಾದರಿ ಡೇಟಾದ ಪ್ರತ್ಯೇಕ ಡೇಟಾಬೇಸ್ ಬಳಸುತ್ತದೆ. ಯಾವ ಇಮೇಲ್ ಅಥವಾ ಸಂದೇಶವೂ ಕಳುಹಿಸುವುದಿಲ್ಲ, ಇಲ್ಲಿನ ಯಾವುದೂ ನೈಜ ದೂರುಗಳ ಮೇಲೆ ಪರಿಣಾಮ ಬೀರುವುದಿಲ್ಲ. ಯಾವುದೇ ಸಂದರ್ಶಕರು ಇದನ್ನು ಮರುಹೊಂದಿಸಬಹುದು.",
  "The department reports this issue as resolved. It has not yet been verified.": "ಇಲಾಖೆ ಈ ಸಮಸ್ಯೆಯನ್ನು ಪರಿಹರಿಸಲಾಗಿದೆ ಎಂದು ವರದಿ ಮಾಡಿದೆ. ಇದು ಇನ್ನೂ ದೃಢೀಕರಣವಾಗಿಲ್ಲ.",
  "The department will handle complaints in this jurisdiction and all of its sub-jurisdictions, unless a closer unit exists.": "ಹತ್ತಿರದ ಘಟಕವಿಲ್ಲದಿದ್ದರೆ, ಈ ಇಲಾಖೆ ಈ ವ್ಯಾಪ್ತಿ ಮತ್ತು ಅದರ ಎಲ್ಲಾ ಉಪ-ವ್ಯಾಪ್ತಿಗಳ ದೂರುಗಳನ್ನು ನಿರ್ವಹಿಸುತ್ತದೆ.",
  "The location decides the jurisdiction, and configured rules decide the responsible department and officer.": "ಸ್ಥಳವು ವ್ಯಾಪ್ತಿಯನ್ನು ನಿರ್ಧರಿಸುತ್ತದೆ, ಸಂರಚಿಸಿದ ನಿಯಮಗಳು ಜವಾಬ್ದಾರ ಇಲಾಖೆ ಮತ್ತು ಅಧಿಕಾರಿಯನ್ನು ನಿರ್ಧರಿಸುತ್ತವೆ.",
  "The neighbourhood": "ಇಡೀ ನೆರೆಹೊರೆ",
  "The whole street": "ಇಡೀ ಬೀದಿ",
  "These are AI suggestions, not decisions. Please verify everything before using it.": "ಇವು AI ಸಲಹೆಗಳು, ನಿರ್ಧಾರಗಳಲ್ಲ. ಬಳಸುವ ಮೊದಲು ಎಲ್ಲವನ್ನೂ ಪರಿಶೀಲಿಸಿ.",
  "These configuration items will be removed with it:": "ಈ ಸಂರಚನಾ ಅಂಶಗಳು ಅದರೊಂದಿಗೆ ತೆಗೆದುಹಾಕಲ್ಪಡುತ್ತವೆ:",
  "These help the department prioritize. Leave anything you are unsure about blank — we never fill in values for you.": "ಇವು ಇಲಾಖೆಗೆ ಆದ್ಯತೆ ನಿರ್ಧರಿಸಲು ಸಹಾಯ ಮಾಡುತ್ತವೆ. ಖಚಿತವಿಲ್ಲದ್ದನ್ನು ಖಾಲಿ ಬಿಡಿ — ನಾವು ನಿಮ್ಮ ಪರವಾಗಿ ಏನನ್ನೂ ತುಂಬುವುದಿಲ್ಲ.",
  "This browser does not support notifications.": "ಈ ಬ್ರೌಸರ್ ಅಧಿಸೂಚನೆಗಳನ್ನು ಬೆಂಬಲಿಸುವುದಿಲ್ಲ.",
  "This complaint was assigned to you. Accept it to confirm you are working on it.": "ಈ ದೂರನ್ನು ನಿಮಗೆ ನಿಯೋಜಿಸಲಾಗಿದೆ. ನೀವು ಇದರ ಮೇಲೆ ಕೆಲಸ ಮಾಡುತ್ತಿರುವುದನ್ನು ದೃಢೀಕರಿಸಲು ಸ್ವೀಕರಿಸಿ.",
  "This file format is not supported. Please upload a supported image, audio or video file.": "ಈ ಫೈಲ್ ಸ್ವರೂಪ ಬೆಂಬಲಿತವಲ್ಲ. ದಯವಿಟ್ಟು ಬೆಂಬಲಿತ ಚಿತ್ರ, ಆಡಿಯೊ ಅಥವಾ ವೀಡಿಯೊ ಫೈಲ್ ಅಪ್‌ಲೋಡ್ ಮಾಡಿ.",
  "This is an internal CivicConnect reference, not a government complaint number.": "ಇದು CivicConnect ಆಂತರಿಕ ಉಲ್ಲೇಖ, ಸರ್ಕಾರಿ ದೂರು ಸಂಖ್ಯೆಯಲ್ಲ.",
  "This is an internal CivicConnect workflow. It has not been submitted to any government portal.": "ಇದು CivicConnect ನ ಆಂತರಿಕ ಕಾರ್ಯಪ್ರವಾಹ. ಇದನ್ನು ಯಾವುದೇ ಸರ್ಕಾರಿ ಪೋರ್ಟಲ್‌ಗೆ ಸಲ್ಲಿಸಿಲ್ಲ.",
  "This is not an emergency service. For emergencies call 112.": "ಇದು ತುರ್ತು ಸೇವೆಯಲ್ಲ. ತುರ್ತು ಸಂದರ್ಭದಲ್ಲಿ 112 ಗೆ ಕರೆ ಮಾಡಿ.",
  "This permanently removes the record. It cannot be undone.": "ಇದು ದಾಖಲೆಯನ್ನು ಶಾಶ್ವತವಾಗಿ ಅಳಿಸುತ್ತದೆ. ಇದನ್ನು ಹಿಂತೆಗೆದುಕೊಳ್ಳಲಾಗದು.",
  "This record is still in use and cannot be deleted.": "ಈ ದಾಖಲೆ ಇನ್ನೂ ಬಳಕೆಯಲ್ಲಿದೆ, ಅಳಿಸಲಾಗದು.",
  "This sends the complaint to the main administration (level 2) with your reason.": "ಇದು ನಿಮ್ಮ ಕಾರಣದೊಂದಿಗೆ ದೂರನ್ನು ಮುಖ್ಯ ಆಡಳಿತಕ್ಕೆ (ಹಂತ 2) ಕಳುಹಿಸುತ್ತದೆ.",
  "This sends the complaint to your department administrator (level 1) with your reason.": "ಇದು ನಿಮ್ಮ ಕಾರಣದೊಂದಿಗೆ ದೂರನ್ನು ನಿಮ್ಮ ಇಲಾಖೆ ಆಡಳಿತಗಾರರಿಗೆ (ಹಂತ 1) ಕಳುಹಿಸುತ್ತದೆ.",
  "Tick only for sample or test data.": "ಮಾದರಿ ಅಥವಾ ಪರೀಕ್ಷಾ ಡೇಟಾಗೆ ಮಾತ್ರ ಆಯ್ಕೆಮಾಡಿ.",
  "Time allowed from submission to resolution, by priority. Set these to the authority's own service standards.": "ಆದ್ಯತೆಯ ಪ್ರಕಾರ ಸಲ್ಲಿಕೆಯಿಂದ ಪರಿಹಾರದವರೆಗೆ ಅನುಮತಿಸಿದ ಸಮಯ. ಇವನ್ನು ಪ್ರಾಧಿಕಾರದ ಸ್ವಂತ ಸೇವಾ ಮಾನದಂಡಗಳಿಗೆ ಹೊಂದಿಸಿ.",
  "Title": "ಶೀರ್ಷಿಕೆ",
