  "Complaints raised and resolved per week, last 12 weeks": "వారానికి నమోదైన మరియు పరిష్కరించిన ఫిర్యాదులు, గత 12 వారాలు",
  "Resolved by you, awaiting verification": "మీరు పరిష్కరించినవి, ధృవీకరణ కోసం వేచి ఉన్నాయి",
  "Waiting for your verification": "మీ ధృవీకరణ కోసం వేచి ఉన్నాయి",
  "Open each complaint, review the evidence and the citizen's response, then approve or reject under Verify resolution.": "ప్రతి ఫిర్యాదును తెరిచి, సాక్ష్యం మరియు పౌరుని స్పందనను సమీక్షించి, 'పరిష్కారాన్ని ధృవీకరించండి' కింద ఆమోదించండి లేదా తిరస్కరించండి.",
  "24 hours": "24 గంటలు",
  "3 days": "3 రోజులు",
  "7 days": "7 రోజులు",
  "A few more details (optional)": "మరికొన్ని వివరాలు (ఐచ్ఛికం)",
  "A grouping such as Engineering, Utilities or Public health.": "ఇంజనీరింగ్, యుటిలిటీలు లేదా ప్రజారోగ్యం వంటి విభాగ సమూహం.",
  "A mapping activates a department in a jurisdiction and creates its own unit there, with its own administrators, officers and complaints. A unit also covers every sub-jurisdiction below it.": "మ్యాపింగ్ ఒక శాఖను ఒక అధికార పరిధిలో సక్రియం చేసి, అక్కడ దాని స్వంత యూనిట్‌ను సృష్టిస్తుంది. ఆ యూనిట్‌కు స్వంత నిర్వాహకులు, అధికారులు మరియు ఫిర్యాదులు ఉంటాయి. యూనిట్ దాని కింద ఉన్న ప్రతి ఉప-పరిధిని కూడా కవర్ చేస్తుంది.",
  "A reopening request is already awaiting review.": "తిరిగి తెరవాలన్న అభ్యర్థన ఇప్పటికే సమీక్ష కోసం వేచి ఉంది.",
  "A short name for the issue, e.g. “Deep pothole outside Ward 4 school gate”.": "సమస్యకు చిన్న పేరు, ఉదా. “వార్డు 4 పాఠశాల గేటు బయట లోతైన గుంత”.",
  "A street or area name, not an exact address.": "వీధి లేదా ప్రాంతం పేరు, ఖచ్చితమైన చిరునామా కాదు.",
  "A suggestion shown to the citizen before they confirmed. Not an official finding.": "పౌరుడు నిర్ధారించే ముందు చూపిన సూచన. ఇది అధికారిక నిర్ణయం కాదు.",
  "AI analysis (optional)": "AI విశ్లేషణ (ఐచ్ఛికం)",
  "AI analysis is not configured on this deployment.": "ఈ సర్వర్‌లో AI విశ్లేషణ ఏర్పాటు చేయలేదు.",
  "AI analysis is unavailable right now.": "AI విశ్లేషణ ప్రస్తుతం అందుబాటులో లేదు.",
  "AI can suggest a title, category and summary from your description, photos, video and voice note. You can skip this and fill in the details yourself.": "మీ వివరణ, ఫోటోలు, వీడియో మరియు వాయిస్ నోట్ నుండి AI శీర్షిక, వర్గం మరియు సారాంశాన్ని సూచించగలదు. మీరు దీనిని దాటవేసి వివరాలు మీరే నింపవచ్చు.",
