  "Choose a role to sign in with sample data. You can switch roles at any time from the banner at the top.": "నమూనా డేటాతో సైన్ ఇన్ చేయడానికి ఒక పాత్రను ఎంచుకోండి. పైన ఉన్న బ్యానర్ నుండి ఎప్పుడైనా పాత్ర మార్చవచ్చు.",
  "Choose department…": "శాఖను ఎంచుకోండి…",
  "Choose new status…": "కొత్త స్థితిని ఎంచుకోండి…",
  "Choose officer…": "అధికారిని ఎంచుకోండి…",
  "Choose…": "ఎంచుకోండి…",
  "Citizen": "పౌరుడు",
  "Citizen reply": "పౌరుని సమాధానం",
  "Citizen's original words": "పౌరుని అసలు మాటలు",
  "Citizens report and track complaints. Officers and administrators sign in to their work portal.": "పౌరులు ఫిర్యాదులను నమోదు చేసి ట్రాక్ చేస్తారు. అధికారులు మరియు నిర్వాహకులు తమ పని పోర్టల్‌లో సైన్ ఇన్ చేస్తారు.",
  "Citizens who say their complaint was not resolved can ask to reopen it. The complaint changes only if you accept.": "తమ ఫిర్యాదు పరిష్కారం కాలేదని భావించే పౌరులు దానిని తిరిగి తెరవమని అడగవచ్చు. మీరు అంగీకరిస్తేనే ఫిర్యాదు మారుతుంది.",
  "Citizens, department officers and administrators all sign in here.": "పౌరులు, శాఖ అధికారులు మరియు నిర్వాహకులు అందరూ ఇక్కడే సైన్ ఇన్ చేస్తారు.",
  "Civic grievance redressal": "పౌర ఫిర్యాదుల పరిష్కారం",
  "CivicConnect is an internal grievance workflow. It is not an emergency service — for immediate danger to life, contact local emergency services.": "CivicConnect ఒక అంతర్గత ఫిర్యాదు వ్యవస్థ. ఇది అత్యవసర సేవ కాదు — ప్రాణాపాయం ఉంటే స్థానిక అత్యవసర సేవలను సంప్రదించండి.",
  "CivicConnect is not an emergency service. If there is an immediate threat to life or safety, contact local emergency services now. Your report will also be flagged for prompt human review.": "CivicConnect అత్యవసర సేవ కాదు. ప్రాణానికి లేదా భద్రతకు తక్షణ ప్రమాదం ఉంటే, వెంటనే స్థానిక అత్యవసర సేవలను సంప్రదించండి. మీ నివేదిక కూడా త్వరిత మానవ సమీక్ష కోసం గుర్తించబడుతుంది.",
  "CivicConnect public grievance system": "CivicConnect ప్రజా ఫిర్యాదుల వ్యవస్థ",
  "Clarification requested": "వివరణ కోరబడింది",
  "Clarification requested from the citizen.": "పౌరుని నుండి వివరణ కోరబడింది.",
  "Clear": "తొలగించండి",
  "Clear all": "అన్నీ తొలగించండి",
  "Click the map to add boundary points ({n}). At least 3 are needed.": "సరిహద్దు బిందువులను జోడించడానికి మ్యాప్‌పై క్లిక్ చేయండి ({n}). కనీసం 3 అవసరం.",
  "Close": "మూసివేయండి",
  "Close escalation": "ఎస్కలేషన్‌ను మూసివేయండి",
  "Closed": "మూసివేయబడింది",
