  "Complaint": "ఫిర్యాదు",
  "Complaint category": "ఫిర్యాదు వర్గం",
  "Complaint lifecycle": "ఫిర్యాదు జీవితచక్రం",
  "Complaint reassigned.": "ఫిర్యాదు తిరిగి కేటాయించబడింది.",
  "Complaint submitted": "ఫిర్యాదు సమర్పించబడింది",
  "Complaint trend": "ఫిర్యాదుల ధోరణి",
  "Complaints": "ఫిర్యాదులు",
  "Complaints are matched to the deepest jurisdiction whose boundary contains their location. Levels without a boundary are reached through their sub-jurisdictions.": "ఫిర్యాదులు వాటి స్థానాన్ని కలిగి ఉన్న అత్యంత లోతైన అధికార పరిధికి సరిపోల్చబడతాయి. సరిహద్దు లేని స్థాయిలను వాటి ఉప-పరిధుల ద్వారా చేరుకుంటారు.",
  "Complaints assigned to you and complaints in your operational areas.": "మీకు కేటాయించిన ఫిర్యాదులు మరియు మీ కార్యాచరణ ప్రాంతాల్లోని ఫిర్యాదులు.",
  "Complaints awaiting routing review": "రూటింగ్ సమీక్ష కోసం వేచి ఉన్న ఫిర్యాదులు",
  "Complaints by jurisdiction": "అధికార పరిధి వారీగా ఫిర్యాదులు",
  "Complaints located in these areas (and their sub-areas) are assigned to this officer automatically. Leave all unticked to cover the whole unit.": "ఈ ప్రాంతాల్లో (మరియు వాటి ఉప-ప్రాంతాల్లో) ఉన్న ఫిర్యాదులు ఈ అధికారికి స్వయంచాలకంగా కేటాయించబడతాయి. మొత్తం యూనిట్‌ను కవర్ చేయడానికి అన్నింటినీ ఎంచుకోకుండా వదిలేయండి.",
  "Complaints not resolved within their deadline are escalated automatically: first to the department administrator, then to the main administration. Officers and department administrators can also escalate manually.": "గడువులోగా పరిష్కారం కాని ఫిర్యాదులు స్వయంచాలకంగా ఎస్కలేట్ అవుతాయి: మొదట శాఖ నిర్వాహకుడికి, తర్వాత ప్రధాన పరిపాలనకు. అధికారులు మరియు శాఖ నిర్వాహకులు కూడా స్వయంగా ఎస్కలేట్ చేయవచ్చు.",
  "Complaints received": "ఫిర్యాదులు అందాయి",
  "Complaints routed to your unit that have no officer yet, usually because no active officer covers the location. Open a complaint to assign it.": "మీ యూనిట్‌కు పంపబడి ఇంకా అధికారి లేని ఫిర్యాదులు, సాధారణంగా ఆ స్థానాన్ని ఏ సక్రియ అధికారి కవర్ చేయకపోవడం వల్ల. కేటాయించడానికి ఫిర్యాదును తెరవండి.",
  "Complaints submitted and resolved per week, last 12 weeks": "వారానికి సమర్పించిన మరియు పరిష్కరించిన ఫిర్యాదులు, గత 12 వారాలు",
  "Complaints that cannot be routed automatically appear here. Nothing is ever discarded.": "స్వయంచాలకంగా పంపలేని ఫిర్యాదులు ఇక్కడ కనిపిస్తాయి. ఏదీ ఎప్పుడూ తొలగించబడదు.",
  "Complaints that describe a possible immediate danger are flagged for prompt human review.": "తక్షణ ప్రమాదాన్ని వివరించే ఫిర్యాదులు త్వరిత మానవ సమీక్ష కోసం గుర్తించబడతాయి.",
  "Confidence": "విశ్వసనీయత",
  "Configuration": "కాన్ఫిగరేషన్",
