  "Describe the problem in your language, add photos, and pin the exact spot.": "సమస్యను మీ భాషలో వివరించండి, ఫోటోలు జోడించండి, ఖచ్చితమైన స్థలాన్ని పిన్ చేయండి.",
  "Describe what you see, how it affects people, and where exactly it is (nearby shop, junction, landmark).": "మీరు ఏమి చూస్తున్నారు, ఇది ప్రజలను ఎలా ప్రభావితం చేస్తుంది మరియు ఖచ్చితంగా ఎక్కడ ఉంది (సమీపంలోని దుకాణం, కూడలి, గుర్తు) వివరించండి.",
