  "Each complaint has a service deadline. Overdue complaints are escalated automatically.": "ప్రతి ఫిర్యాదుకు సేవా గడువు ఉంటుంది. గడువు దాటిన ఫిర్యాదులు స్వయంచాలకంగా ఎస్కలేట్ అవుతాయి.",
  "Each department is registered once. Activate it in specific jurisdictions under Department–Jurisdiction Mapping.": "ప్రతి శాఖ ఒక్కసారే నమోదు చేయబడుతుంది. శాఖ–అధికార పరిధి మ్యాపింగ్‌లో నిర్దిష్ట పరిధుల్లో దానిని సక్రియం చేయండి.",
