  "System health and fixed workflow rules. Technical details are kept here, away from the operational overview.": "వ్యవస్థ ఆరోగ్యం మరియు స్థిర వర్క్‌ఫ్లో నియమాలు. సాంకేతిక వివరాలు కార్యాచరణ అవలోకనానికి దూరంగా ఇక్కడ ఉంచబడ్డాయి.",
  "System status": "వ్యవస్థ స్థితి",
  "Taluk": "తాలూకా",
  "Test notification sent. Check your email, phone or browser.": "పరీక్ష నోటిఫికేషన్ పంపబడింది. మీ ఇమెయిల్, ఫోన్ లేదా బ్రౌజర్‌ను తనిఖీ చేయండి.",
  "Thank you. Your confirmation was recorded.": "ధన్యవాదాలు. మీ నిర్ధారణ నమోదు చేయబడింది.",
  "The GeoJSON could not be read.": "GeoJSONను చదవలేకపోయాము.",
  "The citizen chose not to allow public display of this complaint.": "ఈ ఫిర్యాదును ప్రజలకు ప్రదర్శించడానికి పౌరుడు అనుమతించలేదు.",
  "The citizen reported a possible immediate safety concern. Review promptly.": "పౌరుడు సాధ్యమైన తక్షణ భద్రతా సమస్యను నివేదించారు. వెంటనే సమీక్షించండి.",
  "The configuration is not valid JSON.": "కాన్ఫిగరేషన్ చెల్లుబాటు అయ్యే JSON కాదు.",
  "The demonstration uses a separate database with sample data. No emails or messages are sent, and nothing here affects real complaints. Any visitor can reset it.": "ప్రదర్శన నమూనా డేటాతో వేరే డేటాబేస్‌ను ఉపయోగిస్తుంది. ఇమెయిల్‌లు లేదా సందేశాలు పంపబడవు, ఇక్కడ ఏదీ నిజమైన ఫిర్యాదులను ప్రభావితం చేయదు. ఏ సందర్శకుడైనా దీనిని రీసెట్ చేయవచ్చు.",
  "The department reports this issue as resolved. It has not yet been verified.": "శాఖ ఈ సమస్యను పరిష్కరించినట్లు నివేదించింది. ఇది ఇంకా ధృవీకరించబడలేదు.",
  "The department will handle complaints in this jurisdiction and all of its sub-jurisdictions, unless a closer unit exists.": "ఈ అధికార పరిధిలో మరియు దాని అన్ని ఉప-పరిధుల్లో ఫిర్యాదులను ఈ శాఖ నిర్వహిస్తుంది, దగ్గరి యూనిట్ ఉంటే తప్ప.",
  "The location decides the jurisdiction, and configured rules decide the responsible department and officer.": "స్థానం అధికార పరిధిని నిర్ణయిస్తుంది, కాన్ఫిగర్ చేసిన నియమాలు బాధ్యత వహించే శాఖను మరియు అధికారిని నిర్ణయిస్తాయి.",
  "These are AI suggestions, not decisions. Please verify everything before using it.": "ఇవి AI సూచనలు, నిర్ణయాలు కావు. ఉపయోగించే ముందు దయచేసి అన్నింటినీ తనిఖీ చేయండి.",
  "These configuration items will be removed with it:": "ఈ కాన్ఫిగరేషన్ అంశాలు దానితో పాటు తొలగించబడతాయి:",
  "These help the department prioritize. Leave anything you are unsure about blank — we never fill in values for you.": "ఇవి శాఖకు ప్రాధాన్యత నిర్ణయించడంలో సహాయపడతాయి. మీకు ఖచ్చితంగా తెలియని వాటిని ఖాళీగా ఉంచండి — మేము మీ కోసం విలువలను ఎప్పుడూ నింపము.",
  "This browser does not support notifications.": "ఈ బ్రౌజర్ నోటిఫికేషన్‌లకు మద్దతు ఇవ్వదు.",
  "This complaint was assigned to you. Accept it to confirm you are working on it.": "ఈ ఫిర్యాదు మీకు కేటాయించబడింది. మీరు దానిపై పనిచేస్తున్నారని నిర్ధారించడానికి అంగీకరించండి.",
  "This file format is not supported. Please upload a supported image, audio or video file.": "ఈ ఫైల్ ఫార్మాట్‌కు మద్దతు లేదు. దయచేసి మద్దతు ఉన్న చిత్రం, ఆడియో లేదా వీడియో ఫైల్‌ను అప్‌లోడ్ చేయండి.",
  "This is an internal CivicConnect reference, not a government complaint number.": "ఇది అంతర్గత CivicConnect సూచన సంఖ్య, ప్రభుత్వ ఫిర్యాదు సంఖ్య కాదు.",
  "This is an internal CivicConnect workflow. It has not been submitted to any government portal.": "ఇది అంతర్గత CivicConnect వర్క్‌ఫ్లో. ఇది ఏ ప్రభుత్వ పోర్టల్‌కూ సమర్పించబడలేదు.",
  "This is not an emergency service. For emergencies call 112.": "ఇది అత్యవసర సేవ కాదు. అత్యవసర పరిస్థితుల్లో 112కు కాల్ చేయండి.",
  "This permanently removes the record. It cannot be undone.": "ఇది రికార్డును శాశ్వతంగా తొలగిస్తుంది. దీనిని రద్దు చేయలేరు.",
  "This record is still in use and cannot be deleted.": "ఈ రికార్డు ఇంకా ఉపయోగంలో ఉంది, తొలగించలేరు.",
  "This sends the complaint to the main administration (level 2) with your reason.": "ఇది మీ కారణంతో ఫిర్యాదును ప్రధాన పరిపాలనకు (స్థాయి 2) పంపుతుంది.",
  "This sends the complaint to your department administrator (level 1) with your reason.": "ఇది మీ కారణంతో ఫిర్యాదును మీ శాఖ నిర్వాహకుడికి (స్థాయి 1) పంపుతుంది.",
  "Tick only for sample or test data.": "నమూనా లేదా పరీక్ష డేటా కోసం మాత్రమే ఎంచుకోండి.",
  "Time allowed from submission to resolution, by priority. Set these to the authority's own service standards.": "ప్రాధాన్యత వారీగా సమర్పణ నుండి పరిష్కారం వరకు అనుమతించిన సమయం. వీటిని సంస్థ స్వంత సేవా ప్రమాణాలకు అనుగుణంగా సెట్ చేయండి.",
  "Title": "శీర్షిక",
