  "We could not transcribe the audio. Please retry or provide a written description.": "ఆడియోను లిప్యంతరీకరించలేకపోయాము. దయచేసి మళ్లీ ప్రయత్నించండి లేదా వ్రాతపూర్వక వివరణ ఇవ్వండి.",
