  "Weights must add up to 1.0, and thresholds must satisfy CRITICAL > HIGH > MEDIUM. Every change creates a new audited version.": "బరువుల మొత్తం 1.0 కావాలి, పరిమితులు అత్యవసరం > అధికం > మధ్యస్థం ఉండాలి. ప్రతి మార్పు కొత్త ఆడిట్ వెర్షన్‌ను సృష్టిస్తుంది.",
